<?php require_once 'db.php'; require_admin(); $page_title='Admin panel'; $counts=['Users'=>db()->query("SELECT COUNT(*) n FROM users")->fetch()['n'],'Bookings'=>db()->query("SELECT COUNT(*) n FROM bookings")->fetch()['n'],'Feedback'=>db()->query("SELECT COUNT(*) n FROM feedback")->fetch()['n']]; $items=db()->query("SELECT b.*,u.name AS customer,u.email FROM bookings b JOIN users u ON u.id=b.user_id ORDER BY b.created_at DESC LIMIT 50")->fetchAll(); include 'header.php'; ?>
<section class="section"><div class="eyebrow">ADMIN CONSOLE</div><h1 style="font-size:3rem">Operations overview.</h1><div class="stats"><?php foreach($counts as $label=>$n): ?><div class="stat"><span class="muted"><?= h($label) ?></span><strong><?= (int)$n ?></strong></div><?php endforeach; ?></div><div class="panel"><h2>Recent reservations / orders</h2><div class="table-wrap"><table><thead><tr><th>ID</th><th>Customer</th><th>Item</th><th>Details</th><th>Status</th></tr></thead><tbody><?php foreach($items as $it): ?><tr><td>#<?= (int)$it['id'] ?></td><td><?= h($it['customer']) ?><br><small><?= h($it['email']) ?></small></td><td><?= h($it['item_name']) ?></td><td><?= h($it['details']) ?></td><td><?= h($it['status']) ?></td></tr><?php endforeach; ?></tbody></table></div></div><div class="panel" style="margin-top:20px"><h2>Catalog management</h2><p class="muted">The catalog is seeded through SQL for this lab version. Edit records with phpMyAdmin or add rows in the <?= h('flights') ?> table.</p><a class="btn alt" href="admin_report.php">Open report</a></div></section><?php include 'footer.php'; ?>